    // Reset rail_sizes to track current position in each rail
    @memset(rail_sizes, 0);

    // Fill result
    for (msg, 0..) |char, i| {
        const pos = @intCast(i % cycle);
        const rail = if (pos < rail_count) pos else cycle - pos;
        const idx = offsets[rail] + rail_sizes[rail];
        result[idx] = char;
        rail_sizes[rail] += 1;
    }

    return result;
}
