    const rail_count = rails;
    const cycle = 2 * rail_count - 2;
    const len = msg.len;

    // Calculate size of each rail
    var rail_sizes = try allocator.alloc(usize, rail_count);
    defer allocator.free(rail_sizes);
    @memset(rail_sizes, 0);

    for (msg, 0..) |_, i| {
        const pos = @intCast(i % cycle);
        const rail = if (pos < rail_count) pos else cycle - pos;
        rail_sizes[rail] += 1;
    }

    // Split msg into rails
    var rail_offsets = try allocator.alloc(usize, rail_count);
    defer allocator.free(rail_offsets);

    var sum: usize = 0;
    for (rail_sizes, 0..) |size, i| {
        rail_offsets[i] = sum;
        sum += size;
    }

    // Create a grid to mark positions
    // We need to know which positions in the original message belong to which rail
    var rail_positions = try allocator.alloc(usize, len);
    defer allocator.free(rail_positions);

    for (rail_positions, 0..) |*pos, i| {
        const p = @intCast(i % cycle);
        pos.* = if (p < rail_count) p else cycle - p;
    }

    // Allocate result
    var result = try allocator.alloc(u8, len);

    // Fill result by reading zigzag and taking chars from appropriate rail
    var rail_indices = try allocator.alloc(usize, rail_count);
    defer allocator.free(rail_indices);
    @memset(rail_indices, 0);

