const std = @import("std");
const mem = std.mem;

/// Encodes `msg` using the rail fence cipher. Caller owns the returned memory.
pub fn encode(allocator: mem.Allocator, msg: []const u8, rails: u3) mem.Allocator.Error![]u8 {
    if (rails == 1) {
        return allocator.dupe(u8, msg);
    }

    const rail_count = rails;
    const cycle = 2 * rail_count - 2;
    const len = msg.len;

    // Calculate size of each rail
    var rail_sizes = try allocator.alloc(usize, rail_count);
    defer allocator.free(rail_sizes);
    @memset(rail_sizes, 0);

    for (msg, 0..) |_, i| {
        const pos = @intCast(i % cycle);
        const rail = if (pos < rail_count) pos else cycle - pos;
        rail_sizes[rail] += 1;
    }

    // Allocate result
    var result = try allocator.alloc(u8, len);

    // Calculate starting offsets for each rail in result
    var offsets = try allocator.alloc(usize, rail_count);
    defer allocator.free(offsets);

    var sum: usize = 0;
    for (rail_sizes, 0..) |size, i| {
        offsets[i] = sum;
        sum += size;
    }

    // Reset rail_sizes to use as current positions
    @memset(rail_sizes, 0);

    // Fill result
    for (msg, 0..) |char, i| {
        const pos = @intCast(i % cycle);
        const rail = if (pos < rail_count) pos else cycle - pos;
        const idx = offsets[rail] + rail_sizes[rail];
        result[idx] = char;
        rail_sizes[rail] += 1;
    }

    return result;
}

/// Decodes `msg` using the rail fence cipher. Caller owns the returned memory.
pub fn decode(allocator: mem.Allocator, msg: []const u8, rails: u3) mem.Allocator.Error![]u8 {
    if (rails == 1) {
        return allocator.dupe(u8, msg);
    }

    const rail_count = rails;
    const cycle = 2 * rail_count - 2;
    const len = msg.len;

    // Calculate size of each rail
    var rail_sizes = try allocator.alloc(usize, rail_count);
    defer allocator.free(rail_sizes);
    @memset(rail_sizes, 0);

    for (msg, 0..) |_, i| {
        const pos = @intCast(i % cycle);
        const rail = if (pos < rail_count) pos else cycle - pos;
        rail_sizes[rail] += 1;
    }

    // Calculate offsets for each rail in msg
    var rail_offsets = try allocator.alloc(usize, rail_count);
    defer allocator.free(rail_offsets);

    var sum: usize = 0;
    for (rail_sizes, 0..) |size, i| {
        rail_offsets[i] = sum;
        sum += size;
    }

    // Allocate result
    var result = try allocator.alloc(u8, len);

    // Fill result by iterating through zigzag pattern and picking chars from rails
    var rail_indices = try allocator.alloc(usize, rail_count);
    defer allocator.free(rail_indices);
    @memset(rail_indices, 0);

    for (result, 0..) |*res, i| {
        const pos = @intCast(i % cycle);
        const rail = if (pos < rail_count) pos else cycle - pos;
        const idx = rail_offsets[rail] + rail_indices[rail];
        res.* = msg[idx];
        rail_indices[rail] += 1;
    }

    return result;
}
